  function replaceLegacyHandlers(){
    window.showCreator=function(){openTab('feed');};
    window.ensureMockWorkspace=function(){return $('hoaV888MockWorkspace')||renderShell();};
    window.hoaV888EditTest=function(id){editTest(id);};
  }
  window.HOA_ADMIN_MOCK_V888={
    openTab,
    openBuilder:window.hoaV888OpenMockBuilder,
    openQuestionFeeder:window.hoaV888OpenQuestionFeeder,
    refresh:loadAll
  };

  function start(){
    replaceLegacyHandlers();
    // Do not observe document.body. The Admin Runtime mounts this workspace explicitly
    // when Mock Tests is selected, avoiding global mutation churn and duplicate boot.
    window.hoaV888MountMockWorkspace=()=>{
      if(!isAdmin())return null;
      const root=renderShell();
      try{window.dispatchEvent(new CustomEvent('hoa:mock-workspace-ready',{detail:{version:'V8.88'}}));}catch(_){}
      return root;
    };
    window.hoaV888RefreshMockTests=loadAll;
    window.addEventListener('hoa:question-bank-changed',()=>{if(state.mounted)loadAll({bank:true});});
  }
